insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('484', '돈찍누', 'Don-jjik-nu', 'new-slang', null, '''돈으로 찍어 누르기'' — 실력 대신 돈으로 밀어붙이기', '{"de": "Kurz für „mit Geld plattdrücken“ — Geld statt Können einsetzen", "en": "Short for “crushing it with money” — winning by spending, not skill", "es": "Abreviatura de “aplastar con dinero”: ganar gastando, no con habilidad", "ja": "「金で押しつぶす」の略 — 実力ではなく金でゴリ押しすること", "vi": "Viết tắt của “dùng tiền đè bẹp” — thắng nhờ tiêu tiền chứ không nhờ tài"}'::jsonb, null, '[{"type": "명사", "definition": "''돈으로 찍어 누르기''의 앞 글자를 딴 줄임말. 실력이나 요령으로 풀어야 할 일을 돈(과금·재력)을 쏟아부어 힘으로 밀어붙여 해결하는 것을 말한다. 원래 게임에서 유료 아이템으로 스펙을 끌어올려 보스의 패턴이나 난이도를 무시하고 깨는 것을 가리켰고, 지금은 광고비·물량 공세처럼 재력으로 경쟁을 압도하는 일상 상황에도 쓴다. 대개 비꼬는 뉘앙스가 있다.", "definition_i18n": {"de": "Kurzform aus den Anfangssilben von 돈으로 찍어 누르기, „mit Geld plattdrücken“: etwas, das Können oder Geschick verlangt, einfach durch viel Geld (Ingame-Käufe, Finanzkraft) mit Gewalt lösen. Ursprünglich aus Spielen, wo man sich mit bezahlten Items so hochrüstet, dass Bossmuster und Schwierigkeit egal werden; heute auch im Alltag, wenn Werbebudget oder Masse die Konkurrenz erdrückt. Meist klingt es spöttisch.", "en": "Formed from the first syllables of 돈으로 찍어 누르기, “crushing it with money”: solving something that should take skill or know-how by pouring in money (in-game purchases, sheer wealth) and forcing it through. It started in games, for gearing up with paid items until a boss''s patterns and difficulty no longer matter, and is now used in everyday life too — ad budgets or sheer volume overwhelming the competition. It usually carries a sarcastic edge.", "es": "Formada con las primeras sílabas de 돈으로 찍어 누르기, “aplastar con dinero”: resolver algo que requiere habilidad o maña a base de meter dinero (compras en el juego, poder económico) y forzarlo. Nació en los videojuegos, para subir el nivel con objetos de pago hasta que los patrones y la dificultad del jefe dan igual; hoy se usa también en la vida diaria, cuando el presupuesto publicitario o el volumen arrasan a la competencia. Suele sonar sarcástico.", "ja": "「돈으로 찍어 누르기(金で押しつぶす)」の頭文字を取った略語。実力やコツで解決すべきことを、お金(課金・財力)をつぎ込んで力技で押し切ること。もともとはゲームで有料アイテムでスペックを上げ、ボスのパターンや難易度を無視してクリアすることを指し、今では広告費や物量作戦のように財力で競争を圧倒する日常の場面にも使う。たいてい皮肉のニュアンスがある。", "vi": "Ghép từ âm đầu của 돈으로 찍어 누르기, “dùng tiền đè bẹp”: giải quyết việc lẽ ra cần tài năng hay mẹo bằng cách đổ tiền (nạp game, tài lực) vào để ép cho xong. Ban đầu dùng trong game, chỉ việc nâng cấp bằng vật phẩm trả phí đến mức bỏ qua cả chiêu thức lẫn độ khó của boss; nay dùng cả ngoài đời, khi ngân sách quảng cáo hay số lượng áp đảo đối thủ. Thường mang ý mỉa mai."}, "examples": [{"kor": "이번 보스는 패턴 몰라도 돈찍누로 그냥 깨지더라.", "eng": "You can clear this boss without even knowing the patterns — just throw money at it.", "ja": "今回のボス、パターン知らなくても課金ゴリ押しで普通に倒せたよ。", "es": "A este jefe lo pasas sin saberte los patrones: basta con meterle dinero.", "vi": "Boss lần này không cần biết chiêu, cứ nạp tiền đè là qua.", "de": "Diesen Boss schafft man auch ohne die Muster zu kennen — einfach mit Geld plattmachen."}, {"kor": "결국 광고비로 돈찍누한 거지, 제품이 좋아서 뜬 게 아니야.", "eng": "They just steamrolled it with ad money — it didn''t take off because the product was good.", "ja": "結局広告費でゴリ押ししただけで、製品が良くて売れたわけじゃない。", "es": "Al final lo aplastaron a golpe de publicidad; no triunfó porque el producto fuera bueno.", "vi": "Rốt cuộc là dùng tiền quảng cáo đè thôi, chứ đâu phải sản phẩm tốt mà nổi.", "de": "Die haben es am Ende mit Werbegeld plattgewalzt — nicht, weil das Produkt gut war."}]}]'::jsonb, '''돈으로 찍어 누르기''의 앞 글자를 딴 게임 은어로, 게임에서 쓰던 ''딜찍누''(딜로 찍어 누르기)와 같은 틀에 ''딜'' 대신 ''돈''을 넣은 말이다. 2022년 8월 로스트아크의 신규 군단장 레이드가 공개 하루도 안 돼 고가의 과금 무기를 갖춘 공대에 클리어되자 ''돈찍누 클리어''라는 비판이 기사로 다뤄질 만큼 게이머 사이에 널리 쓰였고, 이후 방송과 SNS를 거쳐 게임 밖 일상어로 넘어왔다. 최초 사용처는 확인되지 않는다.', '{"de": "Gamer-Slang aus den Anfangssilben von 돈으로 찍어 누르기; es folgt demselben Muster wie das Spielerwort 딜찍누 („mit Schaden plattdrücken“), nur mit 돈 (Geld) statt 딜 (Schaden). Als im August 2022 ein neuer Legion-Raid in Lost Ark keinen Tag nach Release von einer Gruppe mit teuren, bezahlten Waffen geschafft wurde, war die Kritik am „돈찍누-Clear“ sogar eine Nachrichtenmeldung wert; danach wanderte das Wort über TV und Social Media in den Alltag. Eine Erstverwendung ist nicht belegt.", "en": "Gamer slang built from the first syllables of 돈으로 찍어 누르기; it follows the same frame as the gaming term 딜찍누 (“crushing it with damage”), with 돈 (money) in place of 딜 (damage). In August 2022, when a new Legion Raid in Lost Ark was cleared less than a day after release by a group running expensive paid weapons, criticism of the “돈찍누 clear” was covered in the gaming press — a sign of how widespread the word already was. It then moved through TV and social media into everyday speech. No first use is documented.", "es": "Jerga gamer formada con las primeras sílabas de 돈으로 찍어 누르기; sigue el mismo molde que el término de juego 딜찍누 (“aplastar con daño”), con 돈 (dinero) en lugar de 딜 (daño). En agosto de 2022, cuando una nueva incursión de Lost Ark se superó en menos de un día con un grupo equipado con armas de pago carísimas, las críticas al “clear 돈찍누” llegaron a la prensa de videojuegos; después pasó por la tele y las redes al habla cotidiana. No consta su primer uso.", "ja": "「돈으로 찍어 누르기」の頭文字を取ったゲーマー用語で、ゲームで使われていた「딜찍누(火力で押しつぶす)」と同じ型に「딜(ダメージ)」の代わりに「돈(金)」を入れた語。2022年8月、ロストアークの新規軍団長レイドが公開から1日も経たずに高価な課金武器をそろえたパーティーにクリアされると「돈찍누クリア」への批判が記事になるほど広く使われ、その後テレビやSNSを通じてゲームの外の日常語になった。初出は確認されていない。", "vi": "Tiếng lóng game ghép từ âm đầu của 돈으로 찍어 누르기; nó theo cùng khuôn với từ game 딜찍누 (“dùng sát thương đè bẹp”), chỉ thay 딜 (sát thương) bằng 돈 (tiền). Tháng 8/2022, khi raid mới của Lost Ark bị một nhóm trang bị vũ khí trả phí đắt đỏ phá đảo chưa đầy một ngày sau khi ra mắt, lời chê “phá đảo kiểu 돈찍누” còn lên cả báo game; sau đó từ này qua truyền hình và mạng xã hội thành từ thường ngày. Không rõ lần dùng đầu tiên."}'::jsonb, '''돈찍누로 깼다'', ''결국 돈찍누네''처럼 쓴다. 남의 성과를 깎아내리거나 허탈함을 드러내는 말이라 당사자 앞에서 쓰면 무례하게 들릴 수 있고, 자기 과금을 두고 ''나도 돈찍누했어''라며 셀프 디스로 쓰기도 한다. 게임에서 온 말이라 친구끼리의 가벼운 자리에서 쓰고, 회사나 공식적인 자리에는 맞지 않는다.', '{"de": "Man sagt etwa 돈찍누로 깼다 („mit Geld plattgemacht“) oder 결국 돈찍누네 („am Ende doch nur Geld“). Da es fremde Leistungen kleinredet oder Frust ausdrückt, wirkt es gegenüber den Betroffenen unhöflich; über eigene Ausgaben sagt man es auch selbstironisch („나도 돈찍누했어“). Als Gamer-Wort passt es unter Freunden, nicht in Büro oder formelle Situationen.", "en": "Used as 돈찍누로 깼다 (“cleared it by throwing money at it”) or 결국 돈찍누네 (“so it was just money in the end”). Because it belittles someone''s achievement or voices frustration, saying it to the person involved can sound rude; people also use it self-deprecatingly about their own spending (나도 돈찍누했어, “I paid my way through too”). Being gamer slang, it suits casual talk among friends, not work or formal settings.", "es": "Se usa como 돈찍누로 깼다 (“lo pasé a golpe de dinero”) o 결국 돈찍누네 (“al final fue solo dinero”). Como resta mérito al logro ajeno o expresa frustración, dicho al interesado puede sonar grosero; también se usa en tono autocrítico sobre el propio gasto (나도 돈찍누했어, “yo también pagué para pasar”). Al ser jerga gamer, va bien entre amigos, no en el trabajo ni en contextos formales.", "ja": "「돈찍누로 깼다(課金ゴリ押しでクリアした)」「결국 돈찍누네(結局金かよ)」のように使う。他人の成果をけなしたり脱力感を表したりする語なので本人の前で言うと失礼に聞こえることがあり、自分の課金について「나도 돈찍누했어(自分も金で押し切った)」と自虐的に使うこともある。ゲーム由来の語なので友達同士の気軽な場で使い、職場や改まった場には合わない。", "vi": "Dùng như 돈찍누로 깼다 (“qua màn nhờ đổ tiền”) hay 결국 돈찍누네 (“rốt cuộc cũng chỉ là tiền”). Vì nó hạ thấp thành quả của người khác hoặc bày tỏ sự chán nản, nói trước mặt người trong cuộc có thể bị coi là bất lịch sự; người ta cũng dùng để tự giễu chuyện mình nạp tiền (나도 돈찍누했어, “tớ cũng đổ tiền mà qua”). Là tiếng lóng game nên hợp khi nói chuyện với bạn bè, không hợp nơi làm việc hay dịp trang trọng."}'::jsonb, array['금수저','플렉스','흙수저'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Pay-to-win steamrolling / crushing it with money"}, {"lang": "🇯🇵 JA", "text": "金でゴリ押し(課金ゴリ押し)"}, {"lang": "🇨🇳 ZH", "text": "氪金碾压"}, {"lang": "🇻🇳 VI", "text": "Dùng tiền đè bẹp"}, {"lang": "🇪🇸 ES", "text": "Aplastar a golpe de dinero"}, {"lang": "🇩🇪 DE", "text": "Mit Geld plattwalzen"}]'::jsonb);
